function Help({ text }) {
  if (!text) return null;
  return <p style={{ fontSize: 12, color: M.inkFaint, marginTop: 3, lineHeight: 1.4, fontFamily: F_BODY }}>{text}</p>;
}

/* ======================================================================
   PRIMITIVAS UI
====================================================================== */

function Label({ children }) {
  return <label style={{ display: "block", fontSize: 13, fontWeight: 600, color: M.ink, fontFamily: F_BODY }}>{children}</label>;
}

const inputBase = {
  width: "100%", border: `1px solid ${M.line}`, borderRadius: 8, padding: "8px 10px",
  fontSize: 14, fontFamily: F_BODY, color: M.ink, background: M.card, marginTop: 6,
  outline: "none", boxSizing: "border-box",
};

function Field({ label, help, children }) {
  return (
    <div style={{ marginBottom: 16 }}>
      <Label>{label}</Label>
      {children}
      <Help text={help} />
    </div>
  );
}

function TextInput({ label, help, value, onChange, placeholder, disabled }) {
  return (
    <Field label={label} help={help}>
      <input
        style={{ ...inputBase, background: disabled ? M.grayPale : M.card }}
        value={value || ""}
        placeholder={placeholder}
        disabled={disabled}
        onChange={(e) => onChange(e.target.value)}
        onFocus={(e) => (e.target.style.borderColor = M.blue)}
        onBlur={(e) => (e.target.style.borderColor = M.line)}
      />
    </Field>
  );
}

function TextArea({ label, help, value, onChange, rows = 3, placeholder, disabled }) {
  return (
    <Field label={label} help={help}>
      <textarea
        style={{ ...inputBase, resize: "vertical", lineHeight: 1.5, background: disabled ? M.grayPale : M.card }}
        rows={rows}
        value={value || ""}
        placeholder={placeholder}
        disabled={disabled}
        onChange={(e) => onChange(e.target.value)}
        onFocus={(e) => (e.target.style.borderColor = M.blue)}
        onBlur={(e) => (e.target.style.borderColor = M.line)}
      />
    </Field>
  );
}

function SelectInput({ label, help, value, onChange, options }) {
  // Si el valor guardado no está entre las opciones (p.ej. texto importado de un documento),
  // se muestra tal cual en lugar de reemplazarlo en pantalla por la primera opción.
  const opts = value && !options.includes(value) ? [value, ...options] : options;
  return (
    <Field label={label} help={help}>
      <select style={{ ...inputBase, cursor: "pointer" }} value={value || ""} onChange={(e) => onChange(e.target.value)}>
        {!value && <option value="">— Elegir —</option>}
        {opts.map((o) => <option key={o} value={o}>{o}</option>)}
      </select>
    </Field>
  );
}

function SectionCard({ title, icon: Icon, children, right, subtitle }) {
  return (
    <div style={{ background: M.card, border: `1px solid ${M.line}`, borderRadius: 12, padding: "20px 22px", marginBottom: 18 }}>
      <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", marginBottom: 14 }}>
        <div>
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            {Icon && <Icon size={17} color={M.blue} />}
            <h3 style={{ fontFamily: F_DISPLAY, fontWeight: 600, fontSize: 16.5, color: M.ink, margin: 0 }}>{title}</h3>
          </div>
          {subtitle && <p style={{ fontSize: 12.5, color: M.inkFaint, fontFamily: F_BODY, margin: "4px 0 0" }}>{subtitle}</p>}
        </div>
        {right}
      </div>
      {children}
    </div>
  );
}

function GhostButton({ children, onClick, icon: Icon, danger, small, active }) {
  return (
    <button
      type="button"
      onClick={onClick}
      style={{
        display: "inline-flex", alignItems: "center", gap: 6,
        padding: small ? "5px 10px" : "8px 14px",
        borderRadius: 8, border: `1px solid ${danger ? M.red : active ? M.blue : M.line}`,
        background: active ? M.blueSoft : "transparent", color: danger ? M.red : active ? M.blueDeep : M.inkSoft,
        fontSize: small ? 12.5 : 13.5, fontFamily: F_BODY, fontWeight: 500, cursor: "pointer",
      }}
    >
      {Icon && <Icon size={small ? 13 : 15} />}
      {children}
    </button>
  );
}

function SolidButton({ children, onClick, icon: Icon, disabled, tone = "blue" }) {
  const bg = disabled ? M.grayPale : tone === "blue" ? M.blue : tone === "green" ? M.green : tone === "red" ? M.red : M.blue;
  return (
    <button
      type="button"
      onClick={disabled ? undefined : onClick}
      style={{
        display: "inline-flex", alignItems: "center", gap: 7, padding: "9px 16px", borderRadius: 8,
        border: "none", background: bg, color: disabled ? M.inkFaint : "#fff", fontSize: 13.5,
        fontFamily: F_BODY, fontWeight: 600, cursor: disabled ? "not-allowed" : "pointer",
      }}
    >
      {Icon && <Icon size={15} />}
      {children}
    </button>
  );
}

