/* Generic repeatable list of small cards, schema-driven */
function RepeatableCards({ title, icon, subtitle, list, set, fields, makeBlank, itemLabel, addLabel = "Agregar" }) {
  const add = () => set([...(list || []), makeBlank()]);
  const update = (id, k, v) => set(list.map((it) => (it.id === id ? { ...it, [k]: v } : it)));
  const remove = (id) => set(list.filter((it) => it.id !== id));
  return (
    <SectionCard title={title} icon={icon} subtitle={subtitle} right={<GhostButton icon={Plus} small onClick={add}>{addLabel}</GhostButton>}>
      {(!list || list.length === 0) && <EmptyHint text="Todavía no hay filas cargadas." />}
      {(list || []).map((item, i) => (
        <div key={item.id} style={{ border: `1px solid ${M.line}`, borderRadius: 10, padding: 14, marginBottom: 12, background: M.cream }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
            <span style={{ fontFamily: F_MONO, fontSize: 11.5, color: M.blue }}>{itemLabel ? itemLabel(item, i) : `FILA ${i + 1}`}</span>
            <GhostButton icon={Trash2} danger small onClick={() => remove(item.id)} />
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 0 }}>
            {fields.map((f) => (
              <div key={f.k} style={{ gridColumn: f.wide ? "1 / span 2" : "auto" }}>
                {f.type === "area" ? (
                  <TextArea label={f.label} value={item[f.k]} onChange={(v) => update(item.id, f.k, v)} rows={f.rows || 2} help={f.help} />
                ) : f.type === "select" ? (
                  <SelectInput label={f.label} value={item[f.k]} onChange={(v) => update(item.id, f.k, v)} options={f.options} />
                ) : (
                  <TextInput label={f.label} value={item[f.k]} onChange={(v) => update(item.id, f.k, v)} help={f.help} />
                )}
              </div>
            ))}
          </div>
        </div>
      ))}
    </SectionCard>
  );
}

