/* ======================================================================
   VALIDACIÓN Y PROGRESO
====================================================================== */

function esPunitivo(texto) {
  if (!texto) return false;
  const low = texto.toLowerCase();
  return PALABRAS_PUNITIVAS.some((p) => low.includes(p));
}

function validarActividad(a) {
  const checks = [];
  const push = (ok, label) => checks.push({ ok: !!ok, label });
  push(a.propositoDidactico.trim(), "Propósito didáctico de la actividad");
  push(a.relacionAnterior.trim() && a.relacionSiguiente.trim(), "Relación con la actividad anterior y siguiente");
  push(a.consigna.textoPantalla.trim() && a.consigna.textoAudio.trim(), "Consigna con texto exacto en pantalla y en audio");
  push(a.pantallas.length > 0, "Al menos una pantalla definida (Bloque F)");
  push(a.interacciones.length > 0, "Al menos una interacción especificada (Bloque G)");
  push(a.estados.length > 1, "Más de un estado definido, no solo correcto/incorrecto (Bloque H)");
  push(a.feedback.length > 0 && a.feedback.every((f) => !esPunitivo(f.textoExacto)), "Feedback completo y sin fórmulas punitivas (Bloque I)");
  push(a.datos.respuestaEsperada.trim(), "Respuesta esperada definida (Bloque O)");
  push(Object.values(a.accesibilidad).every((v) => v && v.trim()), "Accesibilidad completa (Bloque N)");
  push(a.navFinal.cuandoTermina.trim() && a.navFinal.cuandoHabilita.trim(), "Reglas de finalización definidas (Bloque S)");
  push(a.casosLimite.every((c) => c.noAplica || c.comportamiento.trim()), "Casos límite con comportamiento asignado (Bloque T)");
  push(a.matriz.length > 0, "Matriz niño/sistema completa (Bloque V)");
  if (a.numero === 3) push(a.confrontacion.estrategia1Proc.trim() && a.confrontacion.estrategia2Proc.trim() && a.confrontacion.guionPreguntas.trim() && a.confrontacion.tipoInteraccion.trim() && a.confrontacion.frasePuente.trim(), "Bloque J con sus 5 elementos completos");
  const missing = checks.filter((c) => !c.ok);
  const percent = Math.round((checks.filter((c) => c.ok).length / checks.length) * 100);
  return { checks, missing, percent, isComplete: missing.length === 0 };
}

function validarModulo(m) {
  const actVals = m.actividades.map(validarActividad);
  const percentActividades = Math.round(actVals.reduce((s, v) => s + v.percent, 0) / actVals.length);
  const idFields = [m.codigo, m.grado, m.area, m.ejeCurricular, m.contenido, m.titulo, m.docentesResponsables, m.especialistaResponsable];
  const identOk = idFields.every((f) => f && f.trim());
  const fundamentacionOk = [m.fundamentacion.propositoGeneral, m.fundamentacion.aprendizajeEsperado, m.fundamentacion.relacionCurricular, m.fundamentacion.conocimientosPrevios].every((f) => f && f.trim());
  const recursosOk = m.recursos.length > 0;
  const trazabilidadOk = m.trazabilidad.some((t) => t.objetivo && t.objetivo.trim());
  const weights = [
    { ok: identOk, w: 10 },
    { ok: fundamentacionOk, w: 10 },
    { ok: Object.values(m.momentos).every((v) => v && v.trim()), w: 5 },
    { ok: percentActividades === 100, w: 50, partial: percentActividades / 100 },
    { ok: recursosOk, w: 10 },
    { ok: m.tecnicas.trim().length > 0, w: 5 },
    { ok: trazabilidadOk, w: 10 },
  ];
  const percent = Math.round(weights.reduce((s, x) => s + (x.partial !== undefined ? x.partial : x.ok ? 1 : 0) * x.w, 0));
  return { actVals, percentActividades, identOk, fundamentacionOk, recursosOk, trazabilidadOk, percent };
}

function readyForDevChecklist(m) {
  const v = validarModulo(m);
  const allActComplete = v.actVals.every((a) => a.isComplete);
  const noPunitive = m.actividades.every((a) => a.feedback.every((f) => !esPunitivo(f.textoExacto)));
  const results = [
    v.identOk, v.fundamentacionOk, m.actividades.every((a) => a.relacionAnterior && a.relacionSiguiente),
    m.actividades.every((a) => a.consigna.textoPantalla && a.consigna.textoAudio),
    m.actividades.every((a) => a.datos.respuestaEsperada && a.datos.alternativasValidas),
    m.actividades.every((a) => a.estados.length > 1), noPunitive,
    m.navegacion.inicio && m.navegacion.continuar && m.navegacion.volver,
    m.actividades.every((a) => a.pantallas.length > 0),
    m.navegacion.inicio && m.navegacion.continuar,
    m.actividades.every((a) => a.interacciones.length > 0),
    m.recursos.length > 0,
    m.actividades.some((a) => a.sonido.length > 0),
    m.actividades.every((a) => a.personaje.length > 0),
    m.actividades.every((a) => a.pantallas.every((p) => p.animacion)),
    m.actividades.every((a) => a.estados.length > 1),
    m.actividades.every((a) => Object.values(a.accesibilidad).every((x) => x && x.trim())),
    m.actividades.every((a) => a.mapa.puntoEntrada),
    m.actividades.every((a) => a.navFinal.cuandoTermina && a.navFinal.cuandoHabilita),
    m.actividades.every((a) => a.casosLimite.every((c) => c.noAplica || c.comportamiento)),
    ["aprobado_didacticamente", "correccion_editorial", "aprobado_editorialmente", "ready_for_development", "enviado_desarrollo"].includes(m.estado),
    ["aprobado_editorialmente", "ready_for_development", "enviado_desarrollo"].includes(m.estado),
    m.actividades[2].confrontacion.estrategia1Proc && m.actividades[2].confrontacion.guionPreguntas,
  ];
  return READY_FOR_DEV.map((label, i) => ({ label, ok: !!results[i] }));
}

