/* Actualiza un campo anidado de forma inmutable: setIn(obj, ["a","b"], v) */
function setIn(obj, path, v) {
  if (!path.length) return v;
  const [k, ...rest] = path;
  return { ...(obj || {}), [k]: setIn((obj || {})[k], rest, v) };
}

